//! The tokenizer against Hugging Face `tokenizers` (`tokenizer_golden.json`,
//! regenerated by `tools/models/embedding_gemma2/tokenizer_golden.py`), its
//! cost on a long single-word input, and the loader's refusal of malformed
//! files:
//! cargo test -p gufo-embedding-gemma2 --features models --test tokenizer

#![allow(clippy::unwrap_used)]
#![cfg_attr(not(feature = "models"), allow(unused_imports, dead_code))]

mod common;

use std::time::Instant;

use gufo_core::json;
use gufo_embedding_gemma2::Tokenizer;

/// The loader must report malformed files instead of crashing or accepting
/// them. These checks need no model weights.
#[test]
fn malformed_tokenizer_files_fail_with_a_message() {
    let directory = tempfile::tempdir().unwrap();
    let dir = directory.path();
    let error = Tokenizer::load(&dir.join("missing")).err().unwrap();
    assert!(
        !error.is_empty(),
        "a missing directory must fail with a message"
    );
    for contents in [
        "{",
        "[]",
        r#"{"model":{"type":"BPE","vocab":{"a":0},"merges":[["a"]]}}"#,
        r#"{"model":{"type":"Unigram"}} trailing"#,
    ] {
        std::fs::write(dir.join("tokenizer.json"), contents).unwrap();
        let error = Tokenizer::load(dir).err().unwrap();
        assert!(
            !error.is_empty(),
            "malformed tokenizer.json must fail with a message"
        );
    }
    // Shapes that parse as JSON but break the schema name the bad section.
    let sections = r#""normalizer":{"type":"Replace","pattern":{"String":" "},"content":"▁"},"pre_tokenizer":{"type":"Split","pattern":{"String":" "},"behavior":"MergedWithPrevious","invert":false},"#;
    for (model, expected) in [
        (r#""model":[]"#, "invalid model: expected an object"),
        (
            r#""model":{"type":"BPE","vocab":{"a":0.5},"merges":[]}"#,
            "is not an integer",
        ),
    ] {
        std::fs::write(dir.join("tokenizer.json"), format!("{{{sections}{model}}}")).unwrap();
        let error = Tokenizer::load(dir).err().unwrap();
        assert!(
            error.contains(expected),
            "expected '{expected}', got '{error}'"
        );
    }
}

const MAXIMUM_LONG_ENCODE_MILLISECONDS: f64 = 200.0;
const LONG_REPEATS: usize = 6;
// The golden document ends in "! ", so a repeat merges only its trailing
// U+2581 into the next copy's first word. A different tail can change a few
// more tokens; 2 leaves one token of slack.
const LONG_BOUNDARY_TOKENS: usize = 2;

#[cfg(feature = "models")]
#[test]
fn token_ids_match_hugging_face() {
    let root = common::checkpoint("tokenizer.json");
    let start = Instant::now();
    let tokenizer =
        Tokenizer::load(&root).unwrap_or_else(|e| panic!("tokenizer.json must load: {e}"));
    let load_ms = start.elapsed().as_secs_f64() * 1e3;
    assert_eq!(
        tokenizer.vocab_size(),
        262_144,
        "the vocabulary has 262144 entries"
    );
    for (token, id) in [
        ("<pad>", 0),
        ("<eos>", 1),
        ("<bos>", 2),
        ("<unk>", 3),
        ("<mask>", 4),
    ] {
        assert_eq!(tokenizer.token_id(token), Some(id), "special token ids");
    }
    assert!(
        tokenizer.token_id("<0x0A>").is_some(),
        "byte tokens must exist"
    );
    assert!(
        tokenizer.token_id("definitely not a token \x01").is_none(),
        "unknown tokens have no id"
    );

    let golden =
        json::parse(&std::fs::read(common::fixture("tokenizer_golden.json")).unwrap()).unwrap();
    let cases = golden.find("cases").unwrap().items();
    assert!(cases.len() >= 80, "the golden file needs at least 80 cases");
    let mut long_document = String::new();
    let mut long_document_ids = Vec::new();
    for (index, entry) in cases.iter().enumerate() {
        let name = entry.member_str("name", "");
        let text = entry.member_str("text", "");
        let add_special_tokens = entry
            .find("add_special_tokens")
            .is_none_or(|add| add.as_bool(true));
        let expected: Vec<u32> = entry
            .find("ids")
            .unwrap()
            .items()
            .iter()
            .map(|id| id.as_double(0.0) as u32)
            .collect();
        let actual = tokenizer.encode(text.as_bytes(), add_special_tokens);
        if name == "long_document" {
            long_document = text.clone();
            long_document_ids = expected.clone();
        }
        if actual != expected {
            let first = actual
                .iter()
                .zip(&expected)
                .take_while(|(a, e)| a == e)
                .count();
            panic!(
                "case {index} '{name}' differs at token {first}\n  expected {expected:?}\n  \
                 actual   {actual:?}"
            );
        }
    }

    // The whole text merges as one BPE word, so a quadratic merge loop shows
    // up on a long input.
    assert!(
        !long_document.is_empty(),
        "the golden file needs a long_document case"
    );
    let long_text = long_document.repeat(LONG_REPEATS);
    assert!(
        long_text.len() >= 40000,
        "the long text must exceed 40000 bytes"
    );
    let start = Instant::now();
    let long_ids = tokenizer.encode(long_text.as_bytes(), true);
    let long_ms = start.elapsed().as_secs_f64() * 1e3;
    // Without <bos> and <eos>, the long text holds LONG_REPEATS copies of
    // the golden document, give or take a few tokens at each boundary.
    assert!(
        long_document_ids.len() > LONG_BOUNDARY_TOKENS + 2,
        "the golden long document is too short"
    );
    let document_tokens = long_document_ids.len() - 2;
    let expected_tokens = LONG_REPEATS * document_tokens;
    assert!(
        long_ids.len() >= expected_tokens - LONG_REPEATS * LONG_BOUNDARY_TOKENS
            && long_ids.len() <= expected_tokens + 2 + LONG_REPEATS * LONG_BOUNDARY_TOKENS,
        "the long text has {} tokens, expected about {expected_tokens}",
        long_ids.len()
    );
    let stable_tokens = document_tokens - LONG_BOUNDARY_TOKENS;
    assert_eq!(
        long_document_ids[..1 + stable_tokens],
        long_ids[..1 + stable_tokens],
        "the long text must start with the golden long document tokens"
    );
    // Copies between two others encode the same way, so the tokens repeat
    // with the period one more copy adds. The first and last copies differ
    // at their outer edges and are left out.
    let period = long_ids.len()
        - tokenizer
            .encode(
                &long_text.as_bytes()[..long_text.len() - long_document.len()],
                true,
            )
            .len();
    assert!(
        long_ids.len() > 2 + 3 * period,
        "the long text must hold at least four copies"
    );
    assert_eq!(
        long_ids[1 + period..long_ids.len() - 1 - 2 * period],
        long_ids[1 + 2 * period..long_ids.len() - 1 - period],
        "interior copies of the long text must encode identically"
    );
    assert!(
        long_ms < MAXIMUM_LONG_ENCODE_MILLISECONDS,
        "the long text took {long_ms} ms"
    );

    // Invalid UTF-8 and stray bytes must neither crash nor hang.
    let invalid = b"a\xff\xc3\xe2\x82 b\x80\xf0\x9f\x98";
    let invalid_ids = tokenizer.encode(invalid, true);
    assert!(
        invalid_ids.len() > 2 && invalid_ids[0] == 2 && *invalid_ids.last().unwrap() == 1,
        "invalid UTF-8 must still be wrapped by bos and eos"
    );
    assert!(
        tokenizer.encode(b"", false).is_empty(),
        "empty text without specials"
    );
    println!(
        "{} golden cases, load {load_ms:.1} ms, {} byte encode {long_ms:.2} ms",
        cases.len(),
        long_text.len()
    );
}
